import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Difference array: weight[i] = how many times index i appears in the concatenation.
        long[] diff = new long[n + 1], weight = new long[n];
        for (int i = 0; i < m; i++) {
            int l = nextInt(), r = nextInt();
            diff[l]++;
            diff[r + 1]--;
        }
        long cur = 0;
        for (int i = 0; i < n; i++) weight[i] = cur += diff[i];
        // Sort indices by value: pack (value + 1e9, index) into one long.
        long[] order = new long[n];
        for (int i = 0; i < n; i++) order[i] = ((a[i] + 1_000_000_000L) << 18) | i;
        Arrays.sort(order);
        long total = 0, answer = 0; // total = weight of all strictly smaller values
        for (int left = 0; left < n;) {
            int right = left;
            long extra = 0;
            while (right < n && (order[right] >> 18) == (order[left] >> 18)) {
                long w = weight[(int) (order[right] & ((1 << 18) - 1))];
                if (w == 0) answer += total;
                extra += w;
                right++;
            }
            total += extra;
            left = right;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Difference array: weight[i] = how many times index i appears in the concatenation.
	diff := make([]int64, n+1)
	for i := 0; i < m; i++ {
		l, r := nextInt(), nextInt()
		diff[l]++
		diff[r+1]--
	}
	weight := make([]int64, n)
	var cur int64
	for i := 0; i < n; i++ {
		cur += diff[i]
		weight[i] = cur
	}
	// Sort indices by value: pack (value + 1e9, index) into one int64.
	order := make([]int64, n)
	for i := range order {
		order[i] = (a[i]+1_000_000_000)<<18 | int64(i)
	}
	slices.Sort(order)
	var total, answer int64 // total = weight of all strictly smaller values
	for left := 0; left < n; {
		right := left
		var extra int64
		for right < n && order[right]>>18 == order[left]>>18 {
			w := weight[order[right]&(1<<18-1)]
			if w == 0 {
				answer += total
			}
			extra += w
			right++
		}
		total += extra
		left = right
	}
	fmt.Println(answer)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
